reversal.fixed_text:
match ch {
    '\0' => write!(f, "\\0")?,
    '\u{FFFD}' => {
        for &b in self[s..e].as_bytes() {
            write!(f, r"\x{:02X}", b)?;
        }
    }
    // ASCII control characters except \0, \n, \r, \t
    '\x01'..='\x08'
    | '\x0b'
    | '\x0c'
    | '\x0e'..='\x19'
    | '\x7f' => {
        write!(f, "\\x{:02x}", ch as u32)?;
    }
    '\n' | '\r' | '\t' | _ => {
        write!(f, "{}", ch.escape_debug())?;
    }
}

reversal.parent_text:
if ch == '\u{FFFD}' {
    for &b in self[s..e].as_bytes() {
        write!(f, r"\x{:X}", b)?;
    }
} else {
    write!(f, "{}", ch.escape_debug())?;
}
